<?php
declare(strict_types=1);
require __DIR__.'/_bootstrap.php';
admin_require_login();
if (!isset($_SESSION['last_activity'])) $_SESSION['last_activity']=time();
if (time()-(int)$_SESSION['last_activity']>1800) { $_SESSION=[]; session_regenerate_id(true); header('Location: login.php?expired=1'); exit; }
$_SESSION['last_activity']=time();
if ($_SERVER['REQUEST_METHOD']==='POST') {
  admin_verify_csrf();
  $id=clean_text((string)($_POST['ticket_id']??''),32); $status=(string)($_POST['status']??''); $notes=clean_text((string)($_POST['admin_notes']??''),5000);
  $statuses=['Open','In Progress','Waiting for Customer','Resolved','Closed'];
  if (!$id || !in_array($status,$statuses,true)) { http_response_code(422); exit('Invalid ticket update.'); }
  $pdo=db(); $pdo->beginTransaction();
  $q=$pdo->prepare('UPDATE tickets SET status=?,admin_notes=?,updated_at=NOW() WHERE ticket_id=?'); $q->execute([$status,$notes,$id]);
  if ($q->rowCount()>0) $pdo->prepare('INSERT INTO ticket_audit_log(ticket_id,admin_user_id,actor,action,detail,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$id,(int)$_SESSION['admin_id'],(string)($_SESSION['admin_username']??'staff'),'status_updated','Status: '.$status]);
  $pdo->commit(); header('Location: /admin/?updated=1'); exit;
}
$search=clean_text((string)($_GET['q']??''),100); $status=clean_text((string)($_GET['status']??''),40); $where=[]; $args=[];
if ($search!=='') { $where[]='(ticket_id LIKE ? OR full_name LIKE ? OR email LIKE ? OR company LIKE ? OR subject LIKE ?)'; $v='%'.$search.'%'; array_push($args,$v,$v,$v,$v,$v); }
if (in_array($status,['Open','In Progress','Waiting for Customer','Resolved','Closed'],true)) { $where[]='status=?'; $args[]=$status; }
$sql='SELECT ticket_id,full_name,email,phone,company,category,priority,subject,description,device_type,attachment_path,attachment_name,status,admin_notes,created_at,updated_at FROM tickets'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY FIELD(priority,"Urgent","High","Medium","Low"), created_at DESC LIMIT 100';
$q=db()->prepare($sql); $q->execute($args); $rows=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>Ticket Dashboard | TekkRestor</title><link rel="stylesheet" href="/assets/style.css"><style>.ticket-row{background:#fff;padding:1rem;border:1px solid #ddd;border-radius:12px;margin:1rem 0}.ticket-row textarea{width:100%;min-height:70px}.ticket-row .field select{min-width:220px}</style></head><body><main class="container" style="padding:2rem 1rem"><div class="section-head"><span class="kicker">Private staff area</span><h1>Support ticket dashboard</h1><p>Signed in as <?=h((string)($_SESSION['admin_username']??'staff'))?> · <a href="/admin/logout.php">Sign out</a></p></div><?php if(isset($_GET['updated'])): ?><div class="success">Ticket updated.</div><?php endif; ?><form method="get" class="form-card"><div class="form-grid"><div class="field"><label for="q">Search</label><input id="q" name="q" value="<?=h($search)?>" placeholder="Ticket, customer, email, company"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><?php foreach(['Open','In Progress','Waiting for Customer','Resolved','Closed'] as $st): ?><option <?= $status===$st?'selected':'' ?>><?=h($st)?></option><?php endforeach; ?></select></div><div class="field"><button class="btn" type="submit">Filter</button></div></div></form><p><?=count($rows)?> ticket(s) shown (maximum 100).</p><?php foreach($rows as $r): ?><article class="ticket-row"><h2><?=h((string)$r['ticket_id'])?> · <?=h((string)$r['subject'])?></h2><p><strong><?=h((string)$r['priority'])?></strong> · <?=h((string)$r['status'])?> · Created <?=h((string)$r['created_at'])?></p><p><?=h((string)$r['full_name'])?> · <a href="mailto:<?=h((string)$r['email'])?>"><?=h((string)$r['email'])?></a> · <a href="tel:<?=h((string)$r['phone'])?>"><?=h((string)$r['phone'])?></a></p><p><?=h((string)$r['company'])?> · <?=h((string)$r['category'])?> · <?=h((string)$r['device_type'])?></p><p><strong>Description</strong><br><?=nl2br(h((string)$r['description']))?></p><?php if($r['attachment_name']): ?><p>Attachment: <a href="/admin/download.php?ticket=<?=rawurlencode((string)$r['ticket_id'])?>"><?=h((string)$r['attachment_name'])?> — download securely</a></p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=h(admin_csrf())?>"><input type="hidden" name="ticket_id" value="<?=h((string)$r['ticket_id'])?>"><div class="form-grid"><div class="field"><label>Status</label><select name="status"><?php foreach(['Open','In Progress','Waiting for Customer','Resolved','Closed'] as $st): ?><option <?= $r['status']===$st?'selected':'' ?>><?=h($st)?></option><?php endforeach; ?></select></div><div class="field full"><label>Internal notes (not shown to customer)</label><textarea name="admin_notes" maxlength="5000"><?=h((string)$r['admin_notes'])?></textarea></div><div class="field"><button class="btn" type="submit">Save update</button></div></div></form></article><?php endforeach; ?></main></body></html>
